pub fn by_id(id: &str) -> Option<&'static Viewpoint> {
    VIEWPOINTS.iter().find(|v| v.id == id)
}

/// True when the viewpoint permits this element type. An unknown
/// viewpoint id permits everything rather than rejecting a model we
/// simply do not recognise.
pub fn allows(viewpoint: &str, element: ElementType) -> bool {
    match by_id(viewpoint) {
        None => true,
        Some(v) => v.elements.is_empty() || v.elements.contains(&element),
    }
}
